  formSubtext: { fontSize: '0.85rem', color: '#71717a', margin: 0 },
  errorAlert: { backgroundColor: '#180707', color: '#ffffff', padding: '10px 14px', borderRadius: '10px', fontSize: '0.85rem', marginBottom: '16px' },
  successAlert: { backgroundColor: '#22c55e', color: '#ffffff', padding: '10px 14px', borderRadius: '10px', fontSize: '0.85rem', marginBottom: '16px' },
  form: { display: 'flex', flexDirection: 'column', gap: '12px' },
  inputGroup: { display: 'flex', flexDirection: 'column', gap: '4px' },
  labelRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  label: { fontSize: '0.75rem', fontWeight: '700', color: '#18181b', textTransform: 'uppercase', letterSpacing: '0.5px' },
  forgotBtn: { background: 'none', border: 'none', color: '#2563eb', fontSize: '0.75rem', fontWeight: '600', cursor: 'pointer' },
